Node* insert_sorted(Node* head, int value) {
    Node* node = new Node();
    node->data = value;
    node->next = NULL;
    if (!head || head->data >= value) {
        node->next = head;
        return node;
    }
    Node* cur = head;
    while (cur->next && cur->next->data < value) cur = cur->next;
    node->next = cur->next;
    cur->next = node;
    return head;
}

