int is_list_palindrome(Node* head) {
    if (!head || !head->next) return 1;
    Node* slow = head;
    Node* fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    Node* second = slow->next;
    slow->next = NULL;
    Node* prev = NULL;
    Node* cur = second;
    while (cur) {
        Node* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    Node* x = head;
    Node* y = prev;
    while (y) {
        if (x->data != y->data) return 0;
        x = x->next;
        y = y->next;
    }
    return 1;
}

