};

int longest_streak(Node* head) {
    int best = 0, run = 0;
    int prev_val = 0;
    bool has_prev = false;
    for (Node* cur = head; cur != NULL; cur = cur->next) {
        if (has_prev && cur->data == prev_val) run++;
        else run = 1;
        if (run > best) best = run;
        prev_val = cur->data;
        has_prev = true;
    }
    return best;
}

